import React, { useState, useEffect } from 'react';
import axios from 'axios';

function Dashboard({ userId }) {
  const [meal, setMeal] = useState(null);
  const [imageData, setImageData] = useState(null);
  const [userProfile, setUserProfile] = useState(null);
  const [favorites, setFavorites] = useState([]);
  const [newFavorite, setNewFavorite] = useState('');

  useEffect(() => {
    if (userId) {
      fetchMeal();
      fetchUserProfile();
      fetchFavorites();
    }
  }, [userId]);

  const fetchMeal = async () => {
    try {
      const res = await axios.get(`http://localhost:5000/meal/suggest/${userId}`);
      setMeal(res.data);
    } catch (error) {
      console.error('Failed to fetch meal:', error);
    }
  };

  const fetchUserProfile = async () => {
    try {
      const res = await axios.get(`http://localhost:5000/profile/${userId}`);
      setUserProfile(res.data);
    } catch (error) {
      console.error('Failed to fetch user profile:', error);
    }
  };

  const fetchFavorites = async () => {
    try {
      const res = await axios.get(`http://localhost:5000/favorites/${userId}`);
      setFavorites(res.data);
    } catch (error) {
      console.error('Failed to fetch favorites:', error);
    }
  };

  const handleImageUpload = async (e) => {
    const formData = new FormData();
    formData.append('image', e.target.files[0]);
    try {
      const res = await axios.post('http://localhost:5000/meal/image', formData);
      setImageData(res.data);
    } catch (error) {
      console.error('Failed to upload image:', error);
    }
  };

  const addFavorite = async () => {
    if (newFavorite.trim() && meal) {
      try {
        await axios.post(`http://localhost:5000/favorites/${userId}`, { name: newFavorite });
        setNewFavorite('');
        fetchFavorites(); // Refresh favorites list
      } catch (error) {
        console.error('Failed to add favorite:', error);
      }
    }
  };

  if (!userId) return <p style={{ padding: '20px', textAlign: 'center' }}>Please sign in.</p>;

  return (
    <div style={{ padding: '20px' }}>
      <h1>Dashboard</h1>
      {userProfile && (
        <div style={{ border: '1px solid #ccc', padding: '10px', marginBottom: '20px', borderRadius: '8px' }}>
          <h2>User Profile</h2>
          <p>Email: {userProfile.email}</p>
          <p>Weight: {userProfile.weight || 'Not set'} kg</p>
          <p>Calorie Goal: {userProfile.calorie_goal || 'Not set'} kcal</p>
          <p>Preferences: {userProfile.preferences || 'Not set'}</p>
          <input
            type="number"
            placeholder="Weight (kg)"
            onChange={(e) => updateProfile('weight', e.target.value)}
          />
          <input
            type="number"
            placeholder="Calorie Goal (kcal)"
            onChange={(e) => updateProfile('calorie_goal', e.target.value)}
          />
          <input
            type="text"
            placeholder="Preferences (e.g., vegan, low-carb)"
            onChange={(e) => updateProfile('preferences', e.target.value)}
          />
          <button onClick={() => updateProfile()}>Update Profile</button>
        </div>
      )}
      {meal && (
        <div style={{ border: '1px solid #ccc', padding: '10px', marginBottom: '20px', borderRadius: '8px' }}>
          <h2>Today’s Meal Suggestion</h2>
          <img src={`https://via.placeholder.com/200?text=${meal.name}`} alt={meal.name} style={{ width: '100%', borderRadius: '4px' }} />
          <h3>{meal.name}</h3>
          <p>Calories: {meal.calories} kcal</p>
          <p>Ingredients: {meal.ingredients}</p>
          <p>Instructions: {meal.instructions}</p>
          <input
            type="text"
            value={newFavorite}
            onChange={(e) => setNewFavorite(e.target.value)}
            placeholder="Add to favorites..."
          />
          <button onClick={addFavorite}>Add Favorite</button>
        </div>
      )}
      <div>
        <h2>Favorite Meals</h2>
        {favorites.map((favorite, index) => (
          <div key={index} style={{ border: '1px solid #ccc', padding: '5px', margin: '5px 0', borderRadius: '4px' }}>
            {favorite.name}
          </div>
        ))}
      </div>
      <h2>Upload Food Image</h2>
      <input type="file" onChange={handleImageUpload} />
      {imageData && <p>Food: {imageData.food}, Calories: {imageData.calories} kcal</p>}
      <div style={{ marginTop: '20px' }}>
        <h2>Meal Planner</h2>
        <button onClick={() => alert('Coming soon: Weekly meal plan!')}>Generate Weekly Plan</button>
      </div>
    </div>
  );

  const updateProfile = async (field, value) => {
    const updates = {};
    if (field) updates[field] = value || userProfile[field];
    try {
      await axios.post(`http://localhost:5000/profile/${userId}`, updates);
      fetchUserProfile(); // Refresh profile
    } catch (error) {
      console.error('Failed to update profile:', error);
    }
  };
}

export default Dashboard;
